from threetears.evals import Eval

from previews import preview


def show(case):
    """The preview the phone shows on the message's channel."""
    return {"preview": preview(case["body"], case["channel"])}


def as_signed_off(case, out):
    """The preview is the one the design team signed off."""
    return out["preview"] == case["approved"]


signed_off = Eval("data/signed_off.jsonl", runner=show, grader=[as_signed_off], k=1)
